const D = { density: .6, wind: .5, energy: .55, speed: 1, scale: 1, hue: 120, x: .5, y: .9, style: 'garden', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const clp = (v,a,b) => Math.max(a, Math.min(b, v));
const st = P.style;
const intn = (K.intensity != null ? K.intensity : .6);
const sec = (K.section | 0);
const TAU = Math.PI * 2;

// full-canvas render buffer (so P.alpha can composite translucently for VJ mixing)
if (!S.fb || S.fbKey !== width + 'x' + height) { if (S.fb) S.fb.remove(); S.fb = createGraphics(width, height); S.fb.pixelDensity(1); S.fb.colorMode(HSB, 360, 100, 100, 100); S.fbKey = width + 'x' + height; }
const g = S.fb;

// L-system rule presets (axiom + productions). Angle in degrees.
const PRESETS = [
  { axiom:'X', rules:{ X:'F-[[X]+X]+F[+FX]-X', F:'FF' }, ang:22, it:3 },
  { axiom:'X', rules:{ X:'F[+X]F[-X]+X', F:'FF' }, ang:20, it:4 },
  { axiom:'F', rules:{ F:'F[+F]F[-F]F' }, ang:25, it:3 },
  { axiom:'X', rules:{ X:'F[-X][+X]FX', F:'FF' }, ang:27, it:4 },
  { axiom:'F', rules:{ F:'FF+[+F-F-F]-[-F+F+F]' }, ang:22, it:2 },
  { axiom:'F', rules:{ F:'FF-[-F+F]+[+F-F]' }, ang:20, it:3 }
];

function rng(seedInt) { let z = seedInt >>> 0; return () => { z = (z * 1664525 + 1013904223) >>> 0; return z / 4294967296; }; }

function expand(pre) {
  let s = pre.axiom;
  for (let k = 0; k < pre.it; k++) {
    let o = '';
    for (let i = 0; i < s.length; i++) { const c = s[i]; o += (pre.rules[c] !== undefined ? pre.rules[c] : c); if (o.length > 5000) break; }
    s = o; if (s.length > 5000) break;
  }
  return s;
}

function buildPlant(idx, N) {
  const seedInt = ((P.seed * 2654435761) ^ (idx * 40503) ^ (sec * 2246822519) ^ 0xB5) >>> 0;
  const rand = rng(seedInt);
  const pre = PRESETS[Math.floor(rand() * PRESETS.length)];
  const str = expand(pre);
  const angR = pre.ang * Math.PI / 180;
  const cap = Math.floor(90 + P.density * 100); // 90..190 nodes
  const nodes = [{ par:-1, rdx:0, rdy:0, depth:0, thick:1 }];
  let x = 0, y = 0, a = -Math.PI/2, cur = 0, depth = 0;
  const stack = [];
  for (let ci = 0; ci < str.length; ci++) {
    if (nodes.length >= cap) break;
    const c = str[ci];
    if (c === 'F') {
      const L = Math.pow(0.9, depth);
      const dx = Math.cos(a) * L, dy = Math.sin(a) * L;
      x += dx; y += dy;
      nodes.push({ par:cur, rdx:dx, rdy:dy, depth:depth, thick:Math.pow(0.72, depth) });
      cur = nodes.length - 1;
    } else if (c === '+') { a -= angR * (0.82 + rand() * 0.36); }
    else if (c === '-') { a += angR * (0.82 + rand() * 0.36); }
    else if (c === '[') { stack.push([x, y, a, cur, depth]); depth++; }
    else if (c === ']') { const s = stack.pop(); if (s) { x = s[0]; y = s[1]; a = s[2]; cur = s[3]; depth = s[4]; } }
  }
  const n = nodes.length;
  const ax = new Float32Array(n), ay = new Float32Array(n), hf = new Float32Array(n);
  const child = new Uint8Array(n);
  let minY = 0, maxD = 0;
  for (let i = 1; i < n; i++) { const p = nodes[i]; ax[i] = ax[p.par] + p.rdx; ay[i] = ay[p.par] + p.rdy; if (ay[i] < minY) minY = ay[i]; if (p.depth > maxD) maxD = p.depth; child[p.par] = 1; }
  const dH = -minY || 1;
  for (let i = 0; i < n; i++) hf[i] = minY ? ay[i] / minY : 0;
  const targetH = height * (0.42 + rand() * 0.24) * P.scale;
  const scl = targetH / dH;
  const bx = width * ((idx + 0.5) / N) + (P.x - 0.5) * width * 0.5 + (rand() - 0.5) * width * 0.05;
  const by = clp(P.y, 0.55, 1) * height + (rand() - 0.5) * height * 0.02;
  let hueF, flowerHue;
  if (st === 'garden') { hueF = clp(P.hue - 10 + (rand() - 0.5) * 34, 60, 165); flowerHue = [340, 50, 12, 285, 200][Math.floor(rand() * 5)]; }
  else if (st === 'seaweed') { hueF = clp(160 + (rand() - 0.5) * 60, 130, 200); flowerHue = 55 + rand() * 60; }
  else if (st === 'autumn') { hueF = [18, 30, 42, 8][Math.floor(rand() * 4)]; flowerHue = [45, 15, 30][Math.floor(rand() * 3)]; }
  else if (st === 'bioluminescent') { hueF = 190 + rand() * 30; flowerHue = [190, 300, 160][Math.floor(rand() * 3)]; }
  else { hueF = 30; flowerHue = 30; } // ink
  return { nodes, hf, child, maxD, scl, bx, by, hueF, flowerHue, phase: rand() * TAU, wob: 0.7 + rand() * 0.6,
    PX: new Float32Array(n), PY: new Float32Array(n), SW: new Float32Array(n),
    hasFlowers: (st === 'garden' || st === 'autumn'), leafP: 0.55 + rand() * 0.2 };
}

// rebuild garden when seed / style / section / density / scale / hue change (section => new species)
const key = width + 'x' + height + '|' + P.seed + '|' + st + '|' + sec + '|' + P.density.toFixed(2) + '|' + P.scale.toFixed(2) + '|' + P.hue.toFixed(0);
if (S.key !== key) {
  S.key = key;
  S.N = Math.round(3 + P.density * 3);
  S.plants = [];
  for (let i = 0; i < S.N; i++) S.plants.push(buildPlant(i, S.N));
}

// ---------- ground gradient (soft, muted; drifts with section) ----------
let topC, botC;
if (st === 'garden') { topC = [208, 24, 52]; botC = [96, 46, 26]; }
else if (st === 'seaweed') { topC = [192, 52, 42]; botC = [205, 74, 12]; }
else if (st === 'autumn') { topC = [34, 30, 56]; botC = [22, 52, 24]; }
else if (st === 'bioluminescent') { topC = [232, 62, 16]; botC = [250, 70, 6]; }
else { topC = [42, 8, 86]; botC = [40, 12, 78]; } // ink — cream paper
const secShift = Math.sin(K.t * 0.05 + sec * 0.9) * 8;
g.noStroke();
const bands = 46;
for (let i = 0; i < bands; i++) {
  const f = i / (bands - 1);
  const h = lerp(topC[0], botC[0], f) + secShift;
  const s = lerp(topC[1], botC[1], f);
  const b = lerp(topC[2], botC[2], f);
  g.fill(h, clp(s, 0, 100), clp(b, 0, 100));
  g.rect(0, f * height - 1, width, height / bands + 2);
}
// horizon glow near the ground line (garden/autumn) — soft warmth, partial
if (st === 'garden' || st === 'autumn') {
  g.push(); g.blendMode(ADD); g.noStroke();
  const gy = clp(P.y, 0.55, 1) * height;
  g.fill(st === 'autumn' ? 30 : 48, 40, 90, 10 + 6 * Math.sin(K.t * 0.2));
  g.ellipse(width * 0.5, gy, width * 1.2, height * 0.5);
  g.blendMode(BLEND); g.pop();
}

// ---------- draw plants ----------
const tw = K.t * (0.4 + P.speed * 0.6);
const windAmp = 0.12 + P.wind;
const glow = clp(0.62 + P.energy * 0.7 + intn * 0.22 + A.rms * 0.4, 0.3, 1.9);
const plants = S.plants || [];
for (let pi = 0; pi < plants.length; pi++) {
  const pl = plants[pi];
  const nodes = pl.nodes, n = nodes.length, PX = pl.PX, PY = pl.PY, SW = pl.SW, hf = pl.hf, child = pl.child;
  const ws = 0.5 * (Math.sin(tw * 0.37 + pl.phase) + 0.6 * Math.sin(tw * 0.61 * pl.wob + pl.phase * 1.7) + 0.4 * Math.sin(tw * 0.233 - pl.phase))
           + 0.3 * Math.sin(tw * 0.11 + pl.phase * 0.5);
  const wsig = ws * windAmp + A.lowmid * 0.4 * Math.sin(tw * 1.3 + pl.phase);
  PX[0] = pl.bx; PY[0] = pl.by; SW[0] = 0;
  for (let i = 1; i < n; i++) {
    const nd = nodes[i], par = nd.par;
    const bend = wsig * (0.016 + 0.006 * nd.depth);
    const sw = SW[par] + bend; SW[i] = sw;
    const ca = Math.cos(sw), sa = Math.sin(sw);
    const rx = (nd.rdx * ca - nd.rdy * sa) * pl.scl;
    const ry = (nd.rdx * sa + nd.rdy * ca) * pl.scl;
    PX[i] = PX[par] + rx; PY[i] = PY[par] + ry;
  }
  // stems
  for (let i = 1; i < n; i++) {
    const nd = nodes[i], par = nd.par, h = hf[i];
    let sh, ss, sb;
    if (st === 'garden') { sh = pl.hueF - 6 + h * 14; ss = 42 + h * 26; sb = clp((26 + h * 42) * glow, 10, 90); }
    else if (st === 'seaweed') { sh = pl.hueF - 4 + h * 12; ss = 50 + h * 24; sb = clp((24 + h * 40) * glow, 10, 88); }
    else if (st === 'autumn') { sh = pl.hueF + h * 10; ss = 55 + h * 20; sb = clp((30 + h * 44) * glow, 12, 92); }
    else if (st === 'bioluminescent') { sh = pl.hueF; ss = 40 + h * 30; sb = clp((14 + h * 30) * glow, 6, 70); }
    else { sh = 32; ss = 6 + h * 6; sb = clp((14 + h * 16) * (0.8 + P.energy * 0.4), 8, 40); } // ink
    g.stroke(sh, ss, sb, 100);
    g.strokeWeight(Math.max(0.5, nd.thick * u * 0.017 * P.scale));
    g.line(PX[par], PY[par], PX[i], PY[i]);
  }
  // leaves — small blades along branches (mass / fill)
  g.noStroke();
  const leafSz = u * 0.019 * (0.7 + P.scale * 0.4);
  const lp = pl.leafP * (0.5 + P.density * 0.7);
  for (let i = 2; i < n; i++) {
    const nd = nodes[i]; if (nd.depth < 1) continue;
    if (((i * 2654435761) >>> 0) / 4294967296 > lp) continue;
    const par = nd.par, h = hf[i];
    const ang = Math.atan2(PY[i] - PY[par], PX[i] - PX[par]);
    let lh, lsA, lb;
    if (st === 'garden') { lh = pl.hueF - 4 + h * 20; lsA = 58 + h * 18; lb = clp((40 + h * 40) * glow, 14, 95); }
    else if (st === 'seaweed') { lh = pl.hueF + h * 16; lsA = 55 + h * 20; lb = clp((34 + h * 38) * glow, 12, 90); }
    else if (st === 'autumn') { lh = pl.hueF + h * 8 - 4; lsA = 62 + h * 16; lb = clp((44 + h * 40) * glow, 16, 95); }
    else if (st === 'bioluminescent') { lh = pl.hueF + h * 20; lsA = 45 + h * 25; lb = clp((20 + h * 30) * glow, 8, 74); }
    else { lh = 34; lsA = 5; lb = clp((16 + h * 18), 8, 42); } // ink
    g.push();
    g.translate(PX[i], PY[i]);
    g.rotate(ang + Math.PI / 2);
    g.fill(lh, clp(lsA, 0, 100), lb, st === 'ink' ? 92 : 88);
    g.ellipse(0, -leafSz * 0.4, leafSz * 0.62, leafSz * 1.5);
    g.pop();
  }
  // bioluminescent / seaweed tip glow (additive, few)
  if (st === 'bioluminescent' || st === 'seaweed') {
    g.push(); g.blendMode(ADD); g.noStroke();
    let gc = 0;
    for (let i = 1; i < n && gc < 120; i++) {
      if (child[i] !== 0) continue; gc++;
      const pulse = 0.5 + 0.5 * Math.sin(K.t * 1.6 - i * 0.4 + pl.phase);
      const gh = (pl.flowerHue + i * 0.3) % 360;
      g.fill(gh, 55, 100, (10 + pulse * 22) * (0.5 + P.energy) + A.treble * 26);
      g.circle(PX[i], PY[i], u * 0.012 * (0.6 + pulse) * (0.7 + P.scale * 0.4));
    }
    g.blendMode(BLEND); g.pop();
  }
  // flowers at tips (garden / autumn)
  if (pl.hasFlowers) {
    let fc = 0; const fcap = Math.floor(6 + P.density * 8);
    const fsz = u * 0.02 * (0.7 + P.scale * 0.5);
    for (let i = 1; i < n && fc < fcap; i++) {
      if (child[i] !== 0 || hf[i] < 0.35) continue;
      if (((i * 40503 + 7) >>> 0) / 4294967296 > 0.7) continue;
      fc++;
      const cx = PX[i], cy = PY[i];
      const bloom = 0.85 + 0.15 * Math.sin(K.t * 0.9 + i);
      const petals = 5, fh = pl.flowerHue, fb = clp(90 * glow, 60, 100);
      g.noStroke();
      for (let p = 0; p < petals; p++) {
        const pa = (p / petals) * TAU + K.t * 0.15 + i;
        g.push();
        g.translate(cx + Math.cos(pa) * fsz * 0.5, cy + Math.sin(pa) * fsz * 0.5);
        g.rotate(pa);
        g.fill(fh, 74, fb, 92);
        g.ellipse(0, 0, fsz * 0.5, fsz * 0.9 * bloom);
        g.pop();
      }
      g.fill(48, 85, clp(95 * glow, 70, 100), 96);
      g.circle(cx, cy, fsz * 0.45);
    }
  }
}

// atmosphere: drifting motes / spores (few, additive, partial)
g.push(); g.blendMode(ADD); g.noStroke();
const motes = Math.floor(14 + P.density * 16);
for (let i = 0; i < motes; i++) {
  const fx = ((Math.sin(i * 12.9 + P.seed) * 0.5 + 0.5) * width + K.t * (6 + (i % 5) * 3)) % width;
  const fy = (Math.sin(K.t * (0.15 + (i % 4) * 0.05) + i * 2.1) * 0.5 + 0.5) * height * 0.7 + height * 0.06;
  const tw2 = 0.5 + 0.5 * Math.sin(K.t * 1.1 + i);
  const mh = st === 'bioluminescent' ? (190 + (i % 3) * 40) : (st === 'ink' ? 40 : 52);
  const msat = st === 'ink' ? 6 : 40;
  g.fill(mh, msat, 100, (4 + tw2 * 8) * (0.4 + P.energy * 0.8));
  g.circle(fx, fy, u * 0.006 * (0.6 + tw2));
}
g.blendMode(BLEND); g.pop();

// blit — P.alpha lets the whole garden composite translucently over other layers
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
